def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_prev_bids = []
    weak_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) < DAILY_SALARY * 0.8 or opp.get('hp', 0) <= 2:
                weak_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('budget', 0) >= bid:
                    strong_prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev_bids) if strong_prev_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        bid = max(92.0, strong_high + 1.2)
    elif urgent:
        bid = max(78.0, avg_prev + 2.0, strong_high + 0.8 * scarcity)
    else:
        if supply >= 22:
            bid = 18.0 + 6.0 * scarcity
        elif supply >= 19:
            bid = max(28.0, avg_prev * 0.55)
        else:
            bid = max(42.0, avg_prev * 0.72, strong_high * 0.82)

    if weak_opponents >= len(alive_opponents) / 2.0 and not urgent:
        bid *= 0.9

    if day >= 8:
        bid += 4.0 * scarcity
    if day == 1 and not urgent:
        bid *= 0.92

    floor_bid = 8.0
    if urgent:
        floor_bid = 35.0
    if critical:
        floor_bid = 70.0

    bid = max(floor_bid, bid)
    bid = min(budget, bid)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 3))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Alive opponents and immediate reaction from yesterday
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents are alive, conserve
    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids (only immediate previous_trace)
    y_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                y_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Determine pressure level from yesterday
    pressure = 0.0
    if y_bids:
        highest_prev_bid = max(y_bids)
        # If someone bid near the daily salary, the market is hot
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            pressure = 1.0
        elif highest_prev_bid >= DAILY_SALARY * 0.65:
            pressure = 0.7
        else:
            pressure = 0.4

    # Supply-based urgency: higher supply reduces urgency for a given requirement
    # Normalize supply between MIN_SUPPLY..MAX_SUPPLY
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # Base bid: aim around a fraction of daily salary; adjust for HP/no-water days and pressure
    # If I'm low HP or have many no-water days, bid more.
    hp_risk = 0.0
    if hp <= 2:
        hp_risk = 1.0
    elif hp <= 4:
        hp_risk = 0.7
    elif hp <= 6:
        hp_risk = 0.4
    else:
        hp_risk = 0.2

    nw_risk = 0.0
    if no_water_days >= 3:
        nw_risk = 1.0
    elif no_water_days == 2:
        nw_risk = 0.7
    elif no_water_days == 1:
        nw_risk = 0.4
    else:
        nw_risk = 0.2

    urgency = 0.55 * hp_risk + 0.45 * nw_risk

    # Hot market adjustment from yesterday
    # Cindy/Eric seemed to bid ~92; Alex died with similar bid, so avoid always matching the top.
    base = DAILY_SALARY * (0.45 + 0.25 * pressure)

    # Supply reduces need when supply is high
    supply_adjust = (1.0 - supply_factor) * 0.20  # up to +0.20 when supply is low

    bid = base * (1.0 + urgency * 0.65 + supply_adjust)

    # Clamp strategy: never exceed budget; also avoid extreme bids early unless critical
    critical = (hp <= 2) or (no_water_days >= 3)
    if critical:
        bid = min(bid, DAILY_SALARY * 0.95)
    else:
        bid = min(bid, DAILY_SALARY * 0.75)

    # Ensure at least a small meaningful bid when budget allows
    min_bid = 5.0
    if budget <= min_bid:
        return float(max(0.0, budget))

    bid = float(max(min_bid, bid))
    if bid > budget:
        bid = float(budget)

    return float(bid)

